SELECT src,c1,c2 FROM (SELECT 't1' AS src,quote(a) AS c1,quote(b) AS c2 FROM t1 UNION ALL SELECT 't1_a',quote(a),quote(b) FROM t1_a UNION ALL SELECT 't1_b',quote(c),quote(d) FROM t1_b UNION ALL SELECT 't1_c',quote(e),quote(f) FROM t1_c UNION ALL SELECT 't2',quote(k),quote(v) FROM t2 UNION ALL SELECT 't3',quote(k),quote(v) FROM t3 UNION ALL SELECT 't3_a',quote(k),quote(v) FROM t3_a UNION ALL SELECT 't3_b',quote(k),quote(v) FROM t3_b UNION ALL SELECT 'trigger',quote(name),quote(type) FROM sqlite_schema WHERE type='trigger' AND name='t3_insert') ORDER BY src,c1,c2;